INSERT IGNORE INTO screen_intro (id, screen_code, region, text_vi, audio_url, status, updated_at) VALUES
  ('DN-OPEN-BD-01', 'OPEN', 'BD', 'Sương sớm phủ kín Bến Đò Ông Tư rồi! Cùng bò vượt ải giúp ông Tư chở khách qua sông nha!', NULL, 'draft', NOW()),
  ('DN-OPEN-BD-02', 'OPEN', 'BD', 'Bến gỗ sáng nay mờ sương quá. Con đi cùng Cowdi giải sương để chiếc đò sang Cù Lao nhé!', NULL, 'draft', NOW()),
  ('DN-OPEN-BD-03', 'OPEN', 'BD', 'Khách đang đợi bên bờ sông kìa! Con giúp bò và ông Tư hoàn thành ải này để mở đường đò nha!', NULL, 'draft', NOW()),
  ('DN-OPEN-BD-04', 'OPEN', 'BD', 'Mặt sông Bến Đò Ông Tư đang yên ả lắm. Sẵn sàng vượt ải cùng bò cho sương tan biến chưa nào?', NULL, 'draft', NOW()),
  ('DN-OPEN-TG-01', 'OPEN', 'TG', 'Gió lộng trên Tháp Gió đang thổi mạnh lắm! Cùng bò, Mimi và Owlbert vượt qua ải này nhé!', NULL, 'draft', NOW()),
  ('DN-OPEN-TG-02', 'OPEN', 'TG', 'Các cánh quạt Tháp Gió đang chờ làn gió trong lành. Con cùng Cowdi giải sương cho vùng đất nha!', NULL, 'draft', NOW()),
  ('DN-OPEN-TG-03', 'OPEN', 'TG', 'Storm vừa báo có đám sương ghé ngang cánh đồng Tháp Gió. Bắt đầu vượt ải cùng bò nào!', NULL, 'draft', NOW()),
  ('DN-OPEN-TG-04', 'OPEN', 'TG', 'Mimi và Owlbert đang đợi con dưới chân Tháp Gió. Cùng bò chinh phục đủ các màn hôm nay nhé!', NULL, 'draft', NOW()),
  ('DN-OPEN-VS-01', 'OPEN', 'VS', 'Sáng nay sương ghé thăm Vườn Sữa trên cù lao rồi! Cùng Cowdi và Bamboo vượt ải cho vườn sáng nhé!', NULL, 'draft', NOW()),
  ('DN-OPEN-VS-02', 'OPEN', 'VS', 'Đàn gà ở Vườn Sữa đang ríu rít gọi con kìa! Vào ải cùng bò học vui rồi giải sương nha!', NULL, 'draft', NOW()),
  ('DN-OPEN-VS-03', 'OPEN', 'VS', 'Rừng trúc của Bamboo hôm nay hơi mờ sương. Con đồng hành cùng Cowdi vượt ải này thật tự tin nhé!', NULL, 'draft', NOW()),
  ('DN-OPEN-VS-04', 'OPEN', 'VS', 'Bamboo Spirit đang vẫy tay chào con tại Vườn Sữa. Cùng bò bắt đầu hành trình ải học mới nào!', NULL, 'draft', NOW()),
  ('DN-T01-BD-01', 'T-01', 'BD', 'Ngồi trên bến gỗ Bến Đò Ông Tư, cùng bò xem kỹ từng từ mới trước khi đò rời bến nhé!', NULL, 'draft', NOW()),
  ('DN-T01-BD-02', 'T-01', 'BD', 'Ông Tư vừa gửi danh sách từ mới bên bờ sông. Con nghe phát âm rồi nhớ nghĩa cùng Cowdi nha!', NULL, 'draft', NOW()),
  ('DN-T01-BD-03', 'T-01', 'BD', 'Sương sớm còn nhẹ, tranh thủ nhìn rõ từng từ mới với bò để lát nữa vượt sông thật dễ nhé!', NULL, 'draft', NOW()),
  ('DN-T01-BD-04', 'T-01', 'BD', 'Mỗi từ mới như một mái chèo giúp đò đi nhanh hơn. Con xem và nghe kỹ cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T01-TG-01', 'T-01', 'TG', 'Đứng dưới chân Tháp Gió, cùng bò làm quen từng từ mới trước khi gió thổi mạnh lên nhé!', NULL, 'draft', NOW()),
  ('DN-T01-TG-02', 'T-01', 'TG', 'Owlbert mang bảng từ vựng mới tới Tháp Gió rồi. Con nghe rõ âm và xem ví dụ cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T01-TG-03', 'T-01', 'TG', 'Mimi bảo học chắc từ mới là bí quyết đi nhanh qua cánh đồng Tháp Gió. Bắt đầu với Cowdi nhé!', NULL, 'draft', NOW()),
  ('DN-T01-TG-04', 'T-01', 'TG', 'Gió mát ở Tháp Gió giúp đầu óc tỉnh táo lắm. Con xem lần lượt từng từ mới cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T01-VS-01', 'T-01', 'VS', 'Giữa Vườn Sữa xanh mát, cùng Cowdi làm quen bộ từ vựng mới hôm nay thật thong thả nhé!', NULL, 'draft', NOW()),
  ('DN-T01-VS-02', 'T-01', 'VS', 'Bamboo vừa treo bảng từ mới bên rừng trúc Vườn Sữa. Con bấm nghe từng từ cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T01-VS-03', 'T-01', 'VS', 'Đàn gà ở Vườn Sữa đang yên lặng nghe con đọc từ mới đấy. Xem kỹ nghĩa từng từ cùng bò nhé!', NULL, 'draft', NOW()),
  ('DN-T01-VS-04', 'T-01', 'VS', 'Mỗi từ mới ở Vườn Sữa đều có ví dụ quen thuộc. Con ngắm thẻ và nghe phát âm cùng Cowdi nha!', NULL, 'draft', NOW()),
  ('DN-T02-BD-01', 'T-02', 'BD', 'Gió sông Bến Đò Ông Tư thổi nhẹ qua từng tấm thẻ. Con nghe, đoán nghĩa rồi lật kiểm tra cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T02-BD-02', 'T-02', 'BD', 'Ông Tư xếp sẵn xấp thẻ từ trên mũi đò. Con thử nhớ nghĩa trước khi lật thẻ cùng Cowdi nhé!', NULL, 'draft', NOW()),
  ('DN-T02-BD-03', 'T-02', 'BD', 'Mặt sông lấp lánh như những tấm thẻ từ. Nghe kỹ rồi lật xem mình nhớ chuẩn chưa nha!', NULL, 'draft', NOW()),
  ('DN-T02-BD-04', 'T-02', 'BD', 'Đợi khách xuống đò ở Bến Đò Ông Tư, cùng bò lật nhanh vài tấm flashcard cho thật nhớ nhé!', NULL, 'draft', NOW()),
  ('DN-T02-TG-01', 'T-02', 'TG', 'Cánh quạt Tháp Gió quay đều, thẻ từ cũng sẵn sàng lật mở! Con đoán nghĩa trước cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T02-TG-02', 'T-02', 'TG', 'Mimi thách con nghe phát âm ở Tháp Gió rồi đoán nghĩa trước khi lật thẻ đấy. Thử cùng Cowdi nhé!', NULL, 'draft', NOW()),
  ('DN-T02-TG-03', 'T-02', 'TG', 'Owlbert cất từng nghĩa tiếng Việt sau mặt thẻ. Gió Tháp Gió thổi tới đâu, con lật chuẩn tới đó nha!', NULL, 'draft', NOW()),
  ('DN-T02-TG-04', 'T-02', 'TG', 'Storm xếp thẻ ngay ngắn trên cánh đồng Tháp Gió. Nghe âm thật rõ rồi chạm lật thẻ cùng bò nhé!', NULL, 'draft', NOW()),
  ('DN-T02-VS-01', 'T-02', 'VS', 'Dưới bóng rừng trúc Vườn Sữa, cùng bò lật từng thẻ từ xem con nhớ được bao nhiêu rồi nha!', NULL, 'draft', NOW()),
  ('DN-T02-VS-02', 'T-02', 'VS', 'Bamboo chuẩn bị bộ thẻ flashcard bên cạnh Vườn Sữa. Nghe phát âm xong hãy lật kiểm tra nhé!', NULL, 'draft', NOW()),
  ('DN-T02-VS-03', 'T-02', 'VS', 'Đàn gà ở Vườn Sữa cũng tò mò mặt sau tấm thẻ lắm! Con đoán nghĩa rồi chạm lật cùng Cowdi nha!', NULL, 'draft', NOW()),
  ('DN-T02-VS-04', 'T-02', 'VS', 'Ở Vườn Sữa yên bình, lật thẻ chậm rãi sẽ nhớ từ rất lâu. Bắt đầu lượt thẻ cùng bò nhé!', NULL, 'draft', NOW()),
  ('DN-T04-BD-01', 'T-04', 'BD', 'Trên chuyến đò ngang của ông Tư, cùng bò đọc kỹ đoạn văn ngắn rồi trả lời câu hỏi nhé!', NULL, 'draft', NOW()),
  ('DN-T04-BD-02', 'T-04', 'BD', 'Ông Tư kể một câu chuyện nhỏ bên bến gỗ Bến Đò. Con đọc cẩn thận rồi chọn ý đúng cùng Cowdi nha!', NULL, 'draft', NOW()),
  ('DN-T04-BD-03', 'T-04', 'BD', 'Chạm vào từ in đậm trong bài đọc để nghe lại giữa tiếng sóng sông Bến Đò Ông Tư nhé!', NULL, 'draft', NOW()),
  ('DN-T04-BD-04', 'T-04', 'BD', 'Đò trôi êm trên sông sang Cù Lao. Con đọc trọn đoạn văn rồi giải câu hỏi hiểu bài cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T04-TG-01', 'T-04', 'TG', 'Owlbert gửi con một đoạn văn thú vị tại Tháp Gió. Đọc kỹ từng câu rồi trả lời cùng bò nhé!', NULL, 'draft', NOW()),
  ('DN-T04-TG-02', 'T-04', 'TG', 'Ngồi nghỉ dưới bóng Tháp Gió, cùng Cowdi đọc đoạn văn ngắn và tìm chi tiết trả lời câu hỏi nha!', NULL, 'draft', NOW()),
  ('DN-T04-TG-03', 'T-04', 'TG', 'Mimi đã đánh dấu các từ quan trọng trong bài đọc Tháp Gió. Con bấm xem nghĩa khi cần nhé!', NULL, 'draft', NOW()),
  ('DN-T04-TG-04', 'T-04', 'TG', 'Gió lộng trên cánh đồng Tháp Gió không làm con phân tâm đâu. Đọc kỹ đoạn văn cùng bò nào!', NULL, 'draft', NOW()),
  ('DN-T04-VS-01', 'T-04', 'VS', 'Bamboo viết một bài đọc ngắn bên rừng trúc Vườn Sữa. Con đọc chậm rồi trả lời câu hỏi cùng bò nhé!', NULL, 'draft', NOW()),
  ('DN-T04-VS-02', 'T-04', 'VS', 'Ngồi giữa Vườn Sữa nghe đàn gà kêu, cùng Cowdi đọc đoạn văn và tìm đáp án thật chính xác nha!', NULL, 'draft', NOW()),
  ('DN-T04-VS-03', 'T-04', 'VS', 'Các từ mới đều xuất hiện trong đoạn văn Vườn Sữa này đấy. Con đọc kỹ rồi chọn ý đúng nhé!', NULL, 'draft', NOW()),
  ('DN-T04-VS-04', 'T-04', 'VS', 'Bamboo Spirit vừa mở trang sách giữa Vườn Sữa. Cùng bò đọc hiểu trọn vẹn đoạn văn hôm nay nha!', NULL, 'draft', NOW()),
  ('DN-T05-BD-01', 'T-05', 'BD', 'Khách trên Bến Đò Ông Tư đang nói tiếng Anh kìa! Con nghe câu thật kỹ rồi chọn nghĩa đúng nha!', NULL, 'draft', NOW()),
  ('DN-T05-BD-02', 'T-05', 'BD', 'Tiếng sóng sông êm lắm, dễ nghe câu mẫu hơn nhiều. Con nghe xong chọn nghĩa tiếng Việt cùng bò nhé!', NULL, 'draft', NOW()),
  ('DN-T05-BD-03', 'T-05', 'BD', 'Ông Tư nhờ con dịch giúp câu khách vừa nói trên bến gỗ. Nghe lại hoặc nghe chậm nếu cần nha!', NULL, 'draft', NOW()),
  ('DN-T05-BD-04', 'T-05', 'BD', 'Lắng nghe từng câu bên chiếc đò sang Cù Lao rồi chọn đúng nghĩa với Cowdi nhé!', NULL, 'draft', NOW()),
  ('DN-T05-TG-01', 'T-05', 'TG', 'Gió ở Tháp Gió mang theo câu tiếng Anh từ xa. Con lắng nghe thật kỹ rồi chọn nghĩa đúng nha!', NULL, 'draft', NOW()),
  ('DN-T05-TG-02', 'T-05', 'TG', 'Mimi đang đọc mẫu câu trên cánh đồng Tháp Gió. Con nghe kỹ rồi bấm chọn nghĩa tiếng Việt nhé!', NULL, 'draft', NOW()),
  ('DN-T05-TG-03', 'T-05', 'TG', 'Owlbert bảo có thể bấm nút nghe chậm bất cứ lúc nào ở Tháp Gió. Tập trung nghe cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T05-TG-04', 'T-05', 'TG', 'Storm gửi mấy câu tiếng Anh qua làn gió Tháp Gió. Nghe rõ từng chữ rồi chọn nghĩa đúng nhé!', NULL, 'draft', NOW()),
  ('DN-T05-VS-01', 'T-05', 'VS', 'Giữa Vườn Sữa yên tĩnh, lắng nghe câu mẫu rồi chọn nghĩa tiếng Việt thật chuẩn cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T05-VS-02', 'T-05', 'VS', 'Cowdi sẽ đọc rõ từng câu ngay tại Vườn Sữa. Con nghe xong chọn đúng nghĩa bên dưới nhé!', NULL, 'draft', NOW()),
  ('DN-T05-VS-03', 'T-05', 'VS', 'Bên rừng trúc của Bamboo vang lên câu tiếng Anh rất rõ. Nghe kỹ rồi chọn đáp án đúng nha!', NULL, 'draft', NOW()),
  ('DN-T05-VS-04', 'T-05', 'VS', 'Đàn gà ở Vườn Sữa đang trật tự nghe cùng con đấy. Lắng nghe câu rồi chọn nghĩa chuẩn nhé!', NULL, 'draft', NOW()),
  ('DN-T06-BD-01', 'T-06', 'BD', 'Đứng trên bến gỗ Bến Đò Ông Tư, con nghe câu mẫu rồi đọc to theo cho vang khắp mặt sông nhé!', NULL, 'draft', NOW()),
  ('DN-T06-BD-02', 'T-06', 'BD', 'Ông Tư thích nghe con luyện nói tiếng Anh lắm! Bấm mic rồi đọc rõ từng từ cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T06-BD-03', 'T-06', 'BD', 'Khách qua sông Cù Lao đang mỉm cười nghe con nói kìa. Nghe mẫu trước rồi đọc to theo nhé!', NULL, 'draft', NOW()),
  ('DN-T06-BD-04', 'T-06', 'BD', 'Nói to rõ ràng ở Bến Đò Ông Tư sẽ giúp sương sớm tan nhanh hơn đấy. Cùng Cowdi luyện nói nào!', NULL, 'draft', NOW()),
  ('DN-T06-TG-01', 'T-06', 'TG', 'Nói to lên giữa cánh đồng Tháp Gió nào! Nghe câu mẫu rồi bấm mic đọc thật rõ cùng bò nhé!', NULL, 'draft', NOW()),
  ('DN-T06-TG-02', 'T-06', 'TG', 'Owlbert đang lắng nghe giọng phát âm của con ở Tháp Gió. Cứ tự tin đọc rõ từng âm nha!', NULL, 'draft', NOW()),
  ('DN-T06-TG-03', 'T-06', 'TG', 'Mimi cổ vũ con nói thật tự nhiên dưới làn gió Tháp Gió. Nghe chậm trước nếu muốn nhé!', NULL, 'draft', NOW()),
  ('DN-T06-TG-04', 'T-06', 'TG', 'Giọng con đọc chuẩn sẽ vang xa cùng cánh quạt Tháp Gió. Bắt đầu luyện nói với Cowdi nào!', NULL, 'draft', NOW()),
  ('DN-T06-VS-01', 'T-06', 'VS', 'Ở Vườn Sữa, đàn gà và Bamboo rất thích nghe con đọc tiếng Anh! Bấm mic nói theo cùng bò nhé!', NULL, 'draft', NOW()),
  ('DN-T06-VS-02', 'T-06', 'VS', 'Cowdi đọc mẫu một câu giữa Vườn Sữa, con đọc lại thật rõ ràng từng chữ nha!', NULL, 'draft', NOW()),
  ('DN-T06-VS-03', 'T-06', 'VS', 'Rừng trúc Vườn Sữa vang giọng đọc của con sẽ vui lắm đấy. Tự tin nói theo câu mẫu nhé!', NULL, 'draft', NOW()),
  ('DN-T06-VS-04', 'T-06', 'VS', 'Bamboo Spirit đang vỗ tay chờ con luyện nói tại Vườn Sữa. Nghe kỹ rồi bật mic nha!', NULL, 'draft', NOW()),
  ('DN-T07-BD-01', 'T-07', 'BD', 'Sương dày đang tụ lại ở Bến Đò Ông Tư! Trả lời các câu hỏi tổng hợp để giúp đò cập bến nhé!', NULL, 'draft', NOW()),
  ('DN-T07-BD-02', 'T-07', 'BD', 'Chặng cuối tại Bến Đò Ông Tư tới rồi! Cùng bò vượt qua bài tổng hợp để giải sương trên sông nha!', NULL, 'draft', NOW()),
  ('DN-T07-BD-03', 'T-07', 'BD', 'Ông Tư đã sẵn sàng nhổ neo sang Cù Lao. Con làm thật chắc các câu tổng hợp cùng Cowdi nhé!', NULL, 'draft', NOW()),
  ('DN-T07-BD-04', 'T-07', 'BD', 'Vượt qua loạt câu hỏi cuối ở Bến Đò Ông Tư là sương sớm tan ngay. Bình tĩnh chọn đáp án đúng nha!', NULL, 'draft', NOW()),
  ('DN-T07-TG-01', 'T-07', 'TG', 'Mây sương đang chắn cánh quạt Tháp Gió! Cùng bò giải hết loạt câu tổng hợp để đón gió về nhé!', NULL, 'draft', NOW()),
  ('DN-T07-TG-02', 'T-07', 'TG', 'Owlbert và Mimi tin con sẽ vượt qua chặng cuối ở Tháp Gió. Đọc kỹ từng câu hỏi nha!', NULL, 'draft', NOW()),
  ('DN-T07-TG-03', 'T-07', 'TG', 'Cánh đồng Tháp Gió sắp sáng bừng rồi! Làm thật chắc bài kiểm tra tổng hợp cùng Cowdi nhé!', NULL, 'draft', NOW()),
  ('DN-T07-TG-04', 'T-07', 'TG', 'Storm đang giữ gió chờ con hoàn thành chặng cuối Tháp Gió. Chọn đáp án cẩn thận nha!', NULL, 'draft', NOW()),
  ('DN-T07-VS-01', 'T-07', 'VS', 'Sương mù còn vương cuối Vườn Sữa kìa! Trả lời chuẩn các câu tổng hợp để vườn sáng lên nhé!', NULL, 'draft', NOW()),
  ('DN-T07-VS-02', 'T-07', 'VS', 'Bamboo và đàn gà ở Vườn Sữa đang cổ vũ con ở chặng cuối! Bình tĩnh chọn từng đáp án đúng nha!', NULL, 'draft', NOW()),
  ('DN-T07-VS-03', 'T-07', 'VS', 'Chặng tổng kết tại Vườn Sữa đã sẵn sàng. Cùng Cowdi hoàn thành thật tốt để qua ải nhé!', NULL, 'draft', NOW()),
  ('DN-T07-VS-04', 'T-07', 'VS', 'Bamboo Spirit chúc con trả lời thật chuẩn loạt câu hỏi cuối ở Vườn Sữa. Cố lên nha!', NULL, 'draft', NOW()),
  ('DN-T08-BD-01', 'T-08', 'BD', 'Trên bến gỗ Bến Đò Ông Tư, con hãy ghép hoặc gõ lại câu tiếng Anh đúng theo nghĩa tiếng Việt nhé!', NULL, 'draft', NOW()),
  ('DN-T08-BD-02', 'T-08', 'BD', 'Ông Tư cần viết vài câu chỉ đường cho khách qua sông. Con xếp câu thật chuẩn cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-T08-BD-03', 'T-08', 'BD', 'Mỗi câu viết đúng là một tấm ván chắc chắn ở Bến Đò Ông Tư. Cần xem lại thì mở Ngữ pháp nhé!', NULL, 'draft', NOW()),
  ('DN-T08-BD-04', 'T-08', 'BD', 'Nhìn kỹ nghĩa tiếng Việt bên sông Cù Lao rồi xếp từng từ thành câu hoàn chỉnh cùng Cowdi nha!', NULL, 'draft', NOW()),
  ('DN-T08-TG-01', 'T-08', 'TG', 'Gió Tháp Gió thổi xáo trộn thứ tự các từ mất rồi! Con xếp hoặc gõ lại thành câu đúng nhé!', NULL, 'draft', NOW()),
  ('DN-T08-TG-02', 'T-08', 'TG', 'Owlbert mang mấy câu tiếng Việt trên Tháp Gió nhờ con viết sang tiếng Anh. Thử sức cùng bò nha!', NULL, 'draft', NOW()),
