  ('DN-T08-TG-04', 'T-08', 'TG', 'Viết chuẩn từng câu dưới chân Tháp Gió để cánh quạt quay nhanh hơn nha! Bắt đầu với Cowdi thôi!', NULL, 'draft', NOW()),
  ('DN-T08-VS-01', 'T-08', 'VS', 'Bên rừng trúc Vườn Sữa, con hãy xếp hoặc gõ lại câu tiếng Anh khớp với nghĩa tiếng Việt nhé!', NULL, 'draft', NOW()),
