  ('DN-F01-BD-01', 'F-01', 'BD', 'Chiếc đò của ông Tư lướt nhẹ qua sương sớm, từng tấm thẻ từ hiện ra trước mắt con nè!', NULL, 'draft', NOW()),
  ('DN-F01-BD-02', 'F-01', 'BD', 'Ngồi êm trên bến gỗ Bến Đò Ông Tư xem trình chiếu từ mới nhé! Chạm thẻ để dừng bất cứ lúc nào!', NULL, 'draft', NOW()),
  ('DN-F01-BD-03', 'F-01', 'BD', 'Sông Cù Lao trôi chậm rãi như nhịp trình chiếu từ mới. Nghe kỹ từ và ví dụ cùng bò nha!', NULL, 'draft', NOW()),
  ('DN-F01-BD-04', 'F-01', 'BD', 'Ông Tư bật đèn bến đò chiếu rõ từng từ mới. Con giữ nút loa nếu muốn nghe đọc chậm nhé!', NULL, 'draft', NOW()),
