  ('DN-F01-TG-03', 'F-01', 'TG', 'Mimi chỉnh tốc độ đọc vừa vặn cho con ở Tháp Gió. Ngắm hình và nghe ví dụ cùng Cowdi nha!', NULL, 'draft', NOW()),
  ('DN-F01-TG-04', 'F-01', 'TG', 'Từng thẻ từ hiện ra theo nhịp cánh quạt Tháp Gió. Nhìn 4 chấm kỹ năng dưới thẻ cùng bò nhé!', NULL, 'draft', NOW()),
