  ('DN-F01-VS-03', 'F-01', 'VS', 'Rừng trúc của Bamboo yên tĩnh lắm, rất hợp xem trình chiếu từ mới. Nghe kỹ cả câu ví dụ nhé!', NULL, 'draft', NOW()),
