  ('DN-F03-BD-04', 'F-03', 'BD', 'Khách qua sông Cù Lao gọi tên từng từ kìa! Nghe kỹ rồi chạm bong bóng đúng để bò hứng nhé!', NULL, 'draft', NOW()),
